use repair_core::{types::*,validation,github,repository,sandbox,store::Store};
use std::{path::PathBuf,fs};
struct Fixture(PathBuf);
impl Fixture{fn new()->Self{let p=std::env::temp_dir().join(format!("repair-test-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));fs::create_dir_all(p.join("src")).unwrap();fs::write(p.join("src/lib.rs"),"pub fn add(a: u32, b: u32) -> u32 { a - b }\n").unwrap();Self(p)}}
impl Drop for Fixture{fn drop(&mut self){let _=fs::remove_dir_all(&self.0);}}
fn proposal()->Proposal{Proposal{explanation:"Addition uses subtraction".into(),citations:vec![Citation{path:"src/lib.rs".into(),start_line:1,snippet:"pub fn add(a: u32, b: u32) -> u32 { a - b }".into()}],planned_files:vec!["src/lib.rs".into()],edits:vec![Edit{path:"src/lib.rs".into(),old:"a - b".into(),new:"a + b".into()}],reproduction:Some(Reproduction{path:"tests/repair_add.rs".into(),content:"#[test]\nfn repair_add() { assert_eq!(fixture_add::add(5, 2), 7, \"REPAIR_ADD_WRONG_RESULT\"); }\n".into(),test_name:"repair_add".into(),failure_marker:"REPAIR_ADD_WRONG_RESULT".into()}),no_fix:false}}
#[test]fn unsafe_paths_rejected(){for p in ["../secret","/etc/passwd","a/../../b",".git/config","src\\x.rs","C:/token","./lib.rs"]{assert!(validation::safe_path(p).is_err(),"{p}")}assert!(validation::safe_path("src/lib.rs").is_ok());}
#[test]fn source_citation_must_be_exact(){let f=Fixture::new();let mut p=proposal();p.citations[0].start_line=2;assert!(validation::validate_proposal(&f.0,&p).is_err());p.citations[0].start_line=1;p.citations[0].snippet="invented".into();assert!(validation::validate_proposal(&f.0,&p).is_err());}
#[test]fn patch_scope_and_unique_old_text(){let f=Fixture::new();let mut p=proposal();p.planned_files=vec!["src/other.rs".into()];assert!(validation::validate_proposal(&f.0,&p).is_err());p=proposal();p.edits[0].old="does not exist".into();assert!(validation::validate_proposal(&f.0,&p).is_err());}
#[test]fn existing_tests_cannot_be_weakened(){let f=Fixture::new();fs::write(f.0.join("src/lib.rs"),"pub fn add(a: u32, b: u32) -> u32 { a - b }\n#[cfg(test)]\nmod tests { fn helper() { assert_eq!(1, 1); } }\n").unwrap();let mut p=proposal();p.edits[0].old="assert_eq!(1, 1)".into();p.edits[0].new="assert!(true)".into();assert!(validation::validate_proposal(&f.0,&p).is_err());}
#[test]fn applies_validated_change_and_detects_tampering(){let f=Fixture::new();let work=f.0.join("work");fs::create_dir_all(work.join("src")).unwrap();fs::copy(f.0.join("src/lib.rs"),work.join("src/lib.rs")).unwrap();let pristine=f.0.join("pristine");fs::create_dir_all(pristine.join("src")).unwrap();fs::copy(f.0.join("src/lib.rs"),pristine.join("src/lib.rs")).unwrap();let p=proposal();validation::apply(&work,&pristine,&p).unwrap();validation::verify_work(&work,&pristine,&p).unwrap();fs::write(work.join("src/lib.rs"),"tampered").unwrap();assert!(validation::verify_work(&work,&pristine,&p).is_err());}
fn obs(code:i32,text:&str)->Observation{Observation{command:vec!["cargo".into(),"test".into()],exit_code:Some(code),output:text.into(),elapsed_ms:1,truncated:false}}
#[test]fn level_three_requires_repeatable_reproduction_and_pass_after(){let p=proposal();let repro=p.reproduction.unwrap();let bad=obs(101,"test repair_add ... FAILED\nREPAIR_ADD_WRONG_RESULT\ntest result: FAILED");let good=obs(0,"test repair_add ... ok\ntest result: ok. 1 passed");let e=sandbox::evaluate(&repro,vec![bad.clone(),bad.clone()],vec![good.clone(),good.clone()]);assert_eq!(e.level,3);let e=sandbox::evaluate(&repro,vec![bad.clone(),good.clone()],vec![good.clone(),good]);assert_eq!(e.level,1);}
#[test]fn compile_failure_and_truncation_not_evidence(){let repro=proposal().reproduction.unwrap();let bad=obs(101,"could not compile\nREPAIR_ADD_WRONG_RESULT");let good=obs(0,"test result: ok.");assert_eq!(sandbox::evaluate(&repro,vec![bad.clone(),bad],vec![good.clone(),good.clone()]).level,1);let mut o=obs(101,"test repair_add ... FAILED\nREPAIR_ADD_WRONG_RESULT");o.truncated=true;assert_eq!(sandbox::evaluate(&repro,vec![o.clone(),o],vec![good.clone(),good]).level,1);}
#[test]fn github_urls_reject_other_hosts_and_options(){assert!(github::parse_repo("https://github.com/rust-lang/rust").is_ok());for s in ["http://github.com/a/b","https://evil.example/a/b","https://github.com/a/b/issues/1","https://github.com/-c/../x","https://github.com/a/b?token=secret"]{assert!(github::parse_repo(s).is_err());}}
#[test]fn archives_reject_symlink_and_parent_traversal(){let f=Fixture::new();let mut builder=tar::Builder::new(Vec::new());let mut h=tar::Header::new_gnu();h.set_size(0);h.set_entry_type(tar::EntryType::Symlink);h.set_mode(0o777);h.set_link_name("/etc/passwd").unwrap();h.set_cksum();builder.append_data(&mut h,"link",std::io::empty()).unwrap();let data=builder.into_inner().unwrap();assert!(repository::unpack(&data[..],&f.0.join("unpack"),false,1000,10).is_err());}
#[test]fn no_fix_cannot_smuggle_edits(){let f=Fixture::new();let mut p=proposal();p.no_fix=true;assert!(validation::validate_proposal(&f.0,&p).is_err());}
#[test]fn store_settings_roundtrip(){let f=Fixture::new();let s=Store::open(f.0.join("data")).unwrap();let mut st=Settings::default();st.model_id="my-model".into();s.save_settings(&st).unwrap();assert_eq!(s.settings().unwrap().model_id,"my-model");}
#[test]fn credentials_are_redacted(){let sample="token ghp_abcdefghijklmnopqrstuvwxyz\n";assert!(repair_core::process::has_secret(sample));assert!(!repair_core::process::scrub(sample).contains("ghp_"));}
#[test]fn fixture_cannot_be_published(){let f=Fixture::new();let engine=repair_core::Engine::new(Store::open(f.0.join("data")).unwrap());let mut run=engine.fixture().unwrap();run.state=State::Review;run.evidence.level=3;let approval=PublishApproval{reviewed_files:vec![],rules_allow_ai:true,duplicates_checked:true,issue_requirement_met:true,human_responsibility:true,title:"Fix".into(),body:String::new(),signoff:false};assert!(github::check_publish(&run,&approval).is_err());}
